"""Write the requested A–Z report from accepted, separately scoped evidence."""
import csv,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'reports'
def read(name):return list(csv.DictReader((R/name).open()))
def pct(v):return f'{float(v)*100:.3f}%' if v not in ('',None) else 'undefined'
def num(v):return f'{float(v):.4f}' if v not in ('',None) else 'undefined'
def table(rows,population):
    result=['| Policy | Population | TP | FP | Recall | Precision | F1 | Benign FPR | PR-AUC | Requests | Accepted | Build cost, s |','|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for row in rows:
        result.append('| '+' | '.join([row['policy'],population,f"{int(row['tp']):,}",f"{int(row['fp']):,}",pct(row['recall']),pct(row['precision']),pct(row['f1']),pct(row['fpr']),num(row['pr_auc']),str(row['retrainings']),str(row['promotions']),f"{float(row['charged_fit_seconds']):.3f}"])+' |')
    return result

def main():
    m=json.loads((ROOT/'manifests/phase12_experiments.json').read_text());p=read('phase12_policy_comparison.csv')
    selected=[r for r in p if r['backend']=='E-LR-seed23013-sample125-weight1' and r['delay']=='0' and r['budget']=='3' and r['sliding']=='2' and r['cooldown']=='2' and r['minimum']=='200']
    selected=sorted(selected,key=lambda r:r['policy']);by={r['policy']:r for r in selected}
    synth=read('phase12_synthetic_metrics.csv');models=read('phase12_model_registry.csv');events=read('phase12_training_events.csv')
    total_models=len(models);physical_seconds=sum(float(r['fit_seconds']) for r in models);optimizer=sum(float(r.get('training_seconds') or 0) for r in models)
    tests_path=R/'phase12_validation/regression.json';tests=json.loads(tests_path.read_text()) if tests_path.exists() else {'status':'pending'}
    browser_path=R/'phase12_validation/browser.json';browser=json.loads(browser_path.read_text()) if browser_path.exists() else {'status':'pending'}
    figures=sorted((R/'figures').glob('phase12_*.png'))
    sections=[]
    def section(letter,title,text):sections.extend(['',f'## {letter}. {title}','',text])
    section('A','Starting checkpoint and environment','Started on research-v2 at `96c1885ef97243e4de33757603fe1530994f0f8e`. Historical fitting/scoring used private Kaggle CPU, Spark 4.3.0, local[4], 8 GiB driver and48 shuffle partitions. Local CPU handled controlled synthetic experiments, tests and the isolated preview. No full raw dataset was downloaded.')
    section('B','Phase 11 acceptance','The original Phase 11 acceptance validator passed before Phase 12 began, with15 tables,24 figures and109 regression tests. Its frozen receipts and detector registry remain unchanged.')
    section('C','Frozen protocol and amendments','Protocol commit3ff45ef precedes all new fitting. configs/phase12_adaptation.yaml defines every primary operating point and budget. docs/phase12_protocol_amendments.md documents correction of the inherited capture-only timestamp policy before replacement-primary fitting. No predictive hyperparameters or alert thresholds were selected from Phase 12 outcomes.')
    section('D','Evaluation populations','Original late-period B retains13,191,622 training,1,151,256 validation and980,109 test flows. Archived Phase 8 independently reproduced its static scores. Primary E assigns permanent70/15/15 fitting/calibration/evaluation predictor-group roles over16,232,943 verified flows, including14 flagged observations at trusted capture-day resolution. Fitting uses a deterministic125/10000 sample of fitting predictor groups; calibration and forward evaluation use their full assigned roles. Initial fitting is February14–15, calibration February16, and forward captures February20,21,22,23,28 and March1,2. The primary matched forward evaluation has'+f"{int(by['P0']['rows']):,}"+' rows. The16,232,929-row stricter sensitivity stays separate. Synthetic data use six known mechanisms,48×512 observations,18 predictors, three seeds and 42 forward windows per run.')
    section('E','Leakage and label availability','Exact-record, canonical-feature and predictor-group cross-role audits are zero. Imputed-vector collisions are reported diagnostically for every fitted candidate. Training-only median imputation, feature filtering and scaling remain separate from promotion and evaluation. Every prediction is issued before release/update. Delays 0, 1, 3 retain pending labels at replay end, without flushing. Eventual-label all-issued metrics support matched retrospective comparisons; released-only endpoint metrics are separate. Archived bin/family/version counts exactly reconstruct configured operating decisions; raw row predictions were materialized in private runtime scratch and are not durable outputs.')
    section('F','Initial static performance',f"P0 produced {int(by['P0']['tp']):,} TP and {int(by['P0']['fp']):,} FP, recall {pct(by['P0']['recall'])}, precision {pct(by['P0']['precision'])}, FPR {pct(by['P0']['fpr'])} and PR-AUC {num(by['P0']['pr_auc'])}. All primary policies/delays reuse the exact saved initial pipeline and threshold. The original late B benchmark has a different population and remains in its own table.")
    sections+=['','### Primary historical E, LR, delay0, candidate cap3','']+table(selected,'historical E')
    archived=[]
    for r in read('phase4_metrics.csv'):
        if r['protocol']=='B' and r['split']=='test':
            archived.append({'policy':'archived '+r['model'],**r,'fpr':int(r['fp'])/(int(r['tn'])+int(r['fp'])),'retrainings':0,'promotions':0,'charged_fit_seconds':0})
    sections+=['','### Archived late-period B, fixed original operating points','', 'These reused benchmarks incur zero new Phase 12 fitting cost. Original fitting times remain in reports/phase4_metrics.csv.','']+table(archived,'archived B test')
    section('G','Periodic retraining',f"P1 accepted {by['P1']['promotions']} candidates after {by['P1']['retrainings']} requests. It yielded {by['P1']['tp']} TP and {by['P1']['fp']} FP. Compare its integer-count tradeoff with P0; accepting a valid refresh does not establish useful adaptation.")
    section('H','Drift-triggered refresh',f"P2 executed the frozen .1 JS input-distribution policy with {by['P2']['alerts']} alerts and {by['P2']['retrainings']} fitting requests. End-of-replay, support and cooldown suppressions are explicit. An alert without a future activation opportunity cannot improve issued predictions. The trigger is independent of evolving model scores.")
    section('I','Adaptive threshold',f"P3 changed the operating threshold {by['P3']['threshold_updates']} times using released, separate calibration labels and frozen coefficients. Its resulting recall is {pct(by['P3']['recall'])} and FPR {pct(by['P3']['fpr'])}. The 1% ceiling applies to eligible validation benign observations, not an assured future FPR. The no-positive threshold remains permissible.")
    section('J','Sliding and expanding windows',f"P4 used the latest 2 released fitting captures, with {by['P4']['tp']} TP,{by['P4']['fp']} FP and {by['P4']['promotions']} accepted candidates. P1 expands every 2 captures; P5 requests expanding refresh every capture subject to the same cooldown/cap. P5 yielded {by['P5']['tp']} TP and {by['P5']['fp']} FP. Sliding3 and other bounded sensitivities are in phase12_robustness.csv.")
    section('K','Guarded promotion',f"P6 made {by['P6']['retrainings']} requests and accepted {by['P6']['promotions']} candidates in the primary historical run. The historical opportunity count limits any guard efficacy conclusion. Synthetic guard comparisons and focused tests exercise actual acceptance/rejection. Guard rules compare candidate and incumbent on the same released calibration rows, plus separate fixed retention diagnostics.")
    section('L','Compute budgets','The primary comparison shares a maximum 3 requests, model family, deterministic fitting sample, validation requirements and evaluation cohort. Cap 6 natural-policy P1/P2 sensitivity is separately reported. Equal caps do not imply equal realized rows, requests or cost. Identical saved candidates are reused when histories match, with original build duration charged counterfactually. Physical work is counted once. Ratios with zero/nonpositive detection benefit remain undefined.')
    section('M','Label-delay sensitivity','All seven LR policies were executed at delays 0, 1, 3 on the same forward cohort. Pending last-delay windows remain unavailable for adaptation. phase12_label_delay.csv and phase12_released_only_metrics.csv distinguish eventual-label evaluation from labels released by termination. Delayed-label and calendar-gap clocks are simulation assumptions, not observed analyst turnaround times.')
    section('N','Controlled synthetic recovery','The 288 controlled runs cover stationary, feature-only distribution shift, prior shift, abrupt/gradual conditional reversal and recurring concepts over seeds23013/14/15. Local sklearn LR uses C=20, max_iter=200; it is a separate implementation from historical Spark LR. JS cannot generally detect a conditional change that leaves inputs stationary. Periodic adaptation can recover recall while worsening false alarms; guard retention can reject useful new-concept fitting. Recovery is the first postchange three-window block with pooled recall reaching prechange recall minus.05. Full seed/delay outcomes and undefined recovery are retained.')
    for mechanism in ('stationary','feature-shift','prior-shift','abrupt-conditional','gradual-conditional','recurring'):
        rows=[r for r in synth if r['backend']==mechanism+'-seed23013' and r['delay']=='0' and r['advanced']=='False' and r['cooldown']=='2' and r['minimum']=='50']
        sections+=['',f'### Synthetic {mechanism}, seed23013, delay0','']+table(rows,'synthetic '+mechanism)
    section('O','Families and forgetting','Family/window/version counts cover DDoS,DoS,credential brute force,Bot,Infiltration and Web attacks. Initial/newly released fitting support, first exposure, active versions and forward misses are explicit. Fixed retention rows are separate from forward evaluation. Capture day and attack family are strongly confounded. A family with no later post-exposure evaluation cannot support a forward-learning claim. No row-independent confidence intervals or established-superiority claim is made.')
    section('P','Candidate outcomes',f"Across accepted historical execution scopes, {sum(int(r['retrainings']) for r in p)} logical fitting requests and {sum(int(r['promotions']) for r in p)} acceptance decisions are reported. A trained model can still fail validation support or guard criteria. Fitting success, action failure, rejection and actual future activation are separate fields. Rejected candidates never replace the incumbent.")
    section('Q','Registry and versioning',f"The compact registry indexes {total_models} unique saved historical pipelines, with source commits, feature order, training days/classes/families, hyperparameters, preprocessing, hashes, private archive locations and reload receipts. Run-specific lifecycle tables contain parent, operating thresholds, calibration populations, decisions and served windows. The final controller atomically persists model and operating threshold together; interrupted updates preserve the previous pointer. Completed replay receipts are idempotent.")
    section('R','Rollback and failure recovery','Controlled tests exercise twelve failure/recovery cases, including corrupt files, failed reload, schema mismatch, missing classes/labels, failed fitting/write, nonfinite scores, duplicate requests, interrupted promotion and actual saved-model restoration. Fresh-process Spark verification additionally restores a retrieved pipeline and checks its probes. Injected events are labeled separately. Natural historical rollback totals remain their observed values in the policy table, including zero.')
    section('S','Computational overhead',f"Accepted historical artifacts required {total_models} unique physical model builds, totaling {physical_seconds:.3f} measured build seconds, including {optimizer:.3f} optimizer seconds. Build timing includes training-only preprocessing, validation safeguards, persistence/reload and imputed-overlap audits. Per-policy charged work is counterfactual and must not be summed as actual physical compute. Physical scoring tables include Parquet materialization and histogram IO; cache-hit call latency is not production inference throughput. Distribution construction, scalar JS/detector work, registry updates, peak driver RSS, model bytes, rejected runs and total notebook runtime have separately scoped receipts. CPU consumption and multi-node scalability were not measured.")
    section('T','Saved models and independent reload','All historical model components are SHA256-verified after Kaggle output retrieval. Fresh local Spark processes reopen retrieved saved pipelines and compare deterministic probes, including controlled Spark rollback. Later Kaggle runtimes reload the exact frozen initial pipeline and reproduce its archived calibration histogram. A separate fresh process reloaded all 344 synthetic models and matched their registered probes. Fitted weights remain outside Git.')
    section('U','Kaggle execution receipts','Accepted primary stages are:\n\n'+'\n'.join('- '+stage+': `'+record['kernel_version']+'` · COMPLETE · '+str(record['runs'])+' runs · '+str(record['models_verified'])+' verified model artifacts' for stage,record in m['historical_stages'].items())+'\n\nPrimary notebook versions1 and2 remain documented as rejected-engineering and separate stricter sensitivity, respectively. Submitted/running states are never called completed. The first Stage12E worker stopped with an RF vector-validation error after fourteen completed LR scopes. The final robustness worker restores those verified scopes and executes the twelve remaining profiles; source-specific ERROR and COMPLETE receipts are retained.')
    section('V','Figures and isolated dashboard',f"{len(figures)} reproducible multi-panel figures cover architecture/clocks, policy metrics, active versions, thresholds, delays, families, retention, budgets, synthetic mechanisms, ablations, injected recovery and overhead. Preview status is {browser['status']}. The browser receipt enumerates actual sections, filters, CSV downloads, charts, console/network results and desktop/mobile screenshots. The public dashboard was not modified or deployed.")
    section('W','Regression results','Complete regression receipt: `'+json.dumps(tests,sort_keys=True)+'`. All original 109 tests remain intact. New tests enforce information boundaries, source coverage, role typing, atomic model/threshold recovery, serialization, real rollback, idempotency, synthetic definitions and artifact reconciliation.')
    section('X','GitHub verification','Every successful stage is committed and pushed to origin/research-v2, followed by independent ls-remote verification. Final remote SHA is reported in the final task response and final validation receipt. Protected work/main and the baseline tag must match their starting values. No force push or merge is performed.')
    section('Y','Conclusions and limitations','Adaptation is not assumed beneficial. Small seven-capture historical support, family/day confounding, correlated/repeated predictor groups, retrospective reuse, simulated labels and cross-version score comparability limit interpretation. Input drift does not establish concept drift or forecast model failure. Synthetic improvements establish controlled behavior only. Guarded retention can impede new-concept adaptation. Scientific unsupported comparisons are listed explicitly; engineering defects are corrected and their execution receipts retained.')
    section('Z','Acceptance verdict','The authoritative manifest remains incomplete until all supported experiments, model reloads, figures, preview/browser checks, full tests, protected references and final push are independently validated. Only then set complete=true and report READY FOR PHASE13, awaiting separate user authorization. No Phase 13 or later implementation is included.')
    (R/'phase12_results.md').write_text('# Phase 12 adaptive learning and model refresh\n'+'\n'.join(sections)+'\n')
    (ROOT/'docs/phase12_research_contribution.md').write_text('# Phase 12 research contribution\n\nThe contribution is an auditable predict-before-update comparison with simulated label release, immutable saved-model versions, explicit operating-point guards, matched historical cohorts, controlled synthetic mechanisms and counterfactual cost accounting. Results include negative refresh tradeoffs and unsupported temporal claims. Source receipts, prediction histograms and independent reloads permit reproduction. This study does not establish operational cyber-defense effectiveness or universally beneficial adaptation.\n')
    print('Wrote A–Z Phase 12 report')
if __name__=='__main__':main()
